using He_Thong_GYM.Models;using Microsoft.Data.SqlClient;using System.Data;
namespace He_Thong_GYM.DAL;
public sealed class TaiChinhDAL
{
 public async Task<List<HoaDonView>> LayHoaDonAsync(){const string q="SELECT h.MaHD,t.HoTen,h.NgayLap,h.TongTien,ISNULL(p.DaTra,0),h.TongTien-ISNULL(p.DaTra,0),h.TrangThai FROM dbo.HoaDon h JOIN dbo.ThanhVien t ON t.MaTV=h.MaTV OUTER APPLY(SELECT SUM(CASE WHEN LoaiGiaoDich=N'Thanh toán' THEN SoTien ELSE -SoTien END) DaTra FROM dbo.ThanhToan WHERE MaHD=h.MaHD AND TrangThai=N'Thành công')p ORDER BY h.MaHD DESC;";var k=new List<HoaDonView>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new HoaDonView{MaHD=r.GetInt32(0),ThanhVien=r.GetString(1),NgayLap=r.GetDateTime(2),TongTien=r.GetDecimal(3),DaThanhToan=r.GetDecimal(4),ConNo=r.GetDecimal(5),TrangThai=r.GetString(6)});return k;}
 public async Task ThanhToanAsync(int hd,decimal tien,string pt,int nv){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_ThanhToanHoaDon",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaHD",hd);m.Parameters.AddWithValue("@SoTien",tien);m.Parameters.AddWithValue("@PhuongThuc",pt);m.Parameters.AddWithValue("@MaNV",nv);var o=m.Parameters.Add("@MaTT",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task HoanTienAsync(int hd,decimal tien,string pt,int nv){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_HoanTien",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaHD",hd);m.Parameters.AddWithValue("@SoTien",tien);m.Parameters.AddWithValue("@PhuongThuc",pt);m.Parameters.AddWithValue("@MaNV",nv);var o=m.Parameters.Add("@MaTT",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();}
}
